280	/// Shared key validation for `sign` and `verify`: non-empty even-length hex.
281	/// The rejected value is never included in the message.
282	fn validate_key_hex(key: &str) -> Result<(), String> {
283	    if key.is_empty() || key.len() % 2 != 0 || !key.bytes().all(|b| b.is_ascii_hexdigit()) {
284	        return Err("--key must be a non-empty, even-length hexadecimal string".to_string());
285	    }
286	    Ok(())
287	}
