// ---------------------------------------------------------------------------
// verify: records hand-authored as if produced by an *external* program that
// only knows the published format 1 contract.
//
// `sign` is never invoked in this section, so a shared bug in this crate's
// sign/verify pair cannot make these tests pass. Every tag is a golden value
// computed independently with Python's hmac/hashlib/struct straight from the
// byte recipe printed in README.md:
//
//   import hmac, hashlib, struct
//   def encode(key_id, version, fields):
//       out = b"authnote-sign-v1"
//       kb = key_id.encode()
//       out += struct.pack(">Q", len(kb)) + kb
//       out += struct.pack(">I", version)
//       out += struct.pack(">Q", len(fields))
//       for f in fields:
//           fb = f.encode()
//           out += struct.pack(">Q", len(fb)) + fb
//       return out
//   hmac.new(bytes.fromhex(key), encode(key_id, version, fields),
//            hashlib.sha256).hexdigest()
//
// The authenticated content exercises what cannot travel through a command
// line: a NUL (U+0000) flanked by text inside a field, plus Chinese, emoji
// (including a UTF-16 surrogate pair spelling) and real newlines.
// ---------------------------------------------------------------------------

/// Independent Python golden tag over:
/// key `cafecafe...cafe`, key_id `密钥\n🙂`, version 42,
/// fields [`前\u{0000}后`, `世界🙂\n第二行`, ``, `世界🙂\n第二行`].
const EXT_KEY: &str = "cafecafecafecafecafecafecafecafe";
const EXT_TAG: &str = "7474105d623bb03a81eb00b34545fcaf7a8c24002c5a6e58ecfdc6172e1d7f9c";

/// Second external producer: key/key-id for the NUL-vs-empty-field goldens.
const EXT2_KEY: &str = "0123456789abcdef";
/// Golden tag for key_id `外部记录`, version 1, one field containing only NUL.
const EXT2_NUL_TAG: &str = "cc556672a3f98087fd6dac8c8a8121f517101f784cb7d163cbe4aea5dfbfc559";
/// Golden tag for the same record with the field being the empty string.
const EXT2_EMPTY_TAG: &str = "79548ce691de6cf5ceeeae27190de8140604615becfd21022a0d34c365f2a0db";

fn expect_external_valid(record: &[u8], key: &str) {
    let out = run_verify(key, record);
    assert_eq!(
        out.status.code(),
        Some(0),
        "expected valid, stderr={:?}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert_eq!(out.stdout, b"{\"valid\":true}\n");
    assert!(
        out.stderr.is_empty(),
        "stderr must be empty on success, got {:?}",
        String::from_utf8_lossy(&out.stderr)
    );
}

fn expect_external_mismatch(record: &[u8], key: &str) {
    let out = run_verify(key, record);
    assert_eq!(
        out.status.code(),
        Some(1),
        "expected mismatch (exit 1), stderr={:?}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert_eq!(out.stdout, b"{\"valid\":false}\n");
    assert!(
        out.stderr.is_empty(),
        "stderr must be empty on mismatch, got {:?}",
        String::from_utf8_lossy(&out.stderr)
    );
}

#[test]
fn external_format1_records_with_nul_chinese_emoji_newline_verify() {
    // Three legal JSON spellings of the SAME decoded record, all carrying the
    // one Python golden tag. Re-spelling, member reordering and reformatting
    // must not require regenerating the tag.

    // (1) Pretty-printed, members in reverse order, padded with JSON
    // whitespace; Chinese/emoji written directly, NUL as \u0000, newline as
    // the short \n escape.
    let pretty = r#"
  {
    "tag" : "7474105d623bb03a81eb00b34545fcaf7a8c24002c5a6e58ecfdc6172e1d7f9c",
    "fields" : [ "前u0000后" , "世界🙂\n第二行", "", "世界🙂\n第二行" ],
    "key_version" : 42,
    "key_id" : "密钥\n🙂",
    "algorithm" : "HMAC-SHA256",
    "format" : 1
  }
"#
    .replace("u0000", "\\u0000"); // keep the NUL escape obvious in the source
    expect_external_valid(pretty.as_bytes(), EXT_KEY);

    // (2) Compact, canonical member order, and pure ASCII: every non-ASCII
    // scalar is a \u escape; the emoji is spelled as its legal UTF-16 surrogate
    // pair, and newlines use \u000a instead of \n.
    let fully_escaped = r#"{"format":1,"algorithm":"HMAC-SHA256","key_id":"密钥u000a🙂","key_version":42,"fields":["前u0000后","世界🙂u000a第二行","","世界🙂u000a第二行"],"tag":"7474105d623bb03a81eb00b34545fcaf7a8c24002c5a6e58ecfdc6172e1d7f9c"}"#
        .replace("u000a", "\\u000a")
        .replace("u0000", "\\u0000");
    expect_external_valid(fully_escaped.as_bytes(), EXT_KEY);

    // (3) Mixed/direct spelling: raw Chinese and emoji bytes, short \n, NUL
    // escaped as \u0000 — verification authenticates decoded text, so it must
    // be byte-for-byte the same conclusion.
    let mixed = r#"{"format":1,"algorithm":"HMAC-SHA256","key_id":"密钥\n🙂","key_version":42,"fields":["前u0000后","世界🙂\n第二行","","世界🙂\n第二行"],"tag":"7474105d623bb03a81eb00b34545fcaf7a8c24002c5a6e58ecfdc6172e1d7f9c"}"#
        .replace("u0000", "\\u0000");
    expect_external_valid(mixed.as_bytes(), EXT_KEY);

    // The same external record under the wrong key is a plain mismatch: the
    // golden tag proves the positive result above is not vacuous.
    expect_external_mismatch(mixed.as_bytes(), "cafecafecafecafecafecafecafecafd");
}

#[test]
fn nul_field_is_neither_empty_nor_truncating_in_external_records() {
    // A field containing a single NUL authenticates differently from an empty
    // field, even though both render as "" in many naive (C-string) toolkits.
    let nul_only = r#"{"format":1,"algorithm":"HMAC-SHA256","key_id":"外部记录","key_version":1,"fields":["u0000"],"tag":"cc556672a3f98087fd6dac8c8a8121f517101f784cb7d163cbe4aea5dfbfc559"}"#
        .replace("u0000", "\\u0000");
    let empty_only = r#"{"format":1,"algorithm":"HMAC-SHA256","key_id":"外部记录","key_version":1,"fields":[""],"tag":"79548ce691de6cf5ceeeae27190de8140604615becfd21022a0d34c365f2a0db"}"#;
    expect_external_valid(nul_only.as_bytes(), EXT2_KEY);
    expect_external_valid(empty_only.as_bytes(), EXT2_KEY);

    // Cross-tagging the two records must fail: NUL is not silently decoded as
    // the empty string.
    let nul_with_empty_tag = r#"{"format":1,"algorithm":"HMAC-SHA256","key_id":"外部记录","key_version":1,"fields":["u0000"],"tag":"79548ce691de6cf5ceeeae27190de8140604615becfd21022a0d34c365f2a0db"}"#
        .replace("u0000", "\\u0000");
    expect_external_mismatch(nul_with_empty_tag.as_bytes(), EXT2_KEY);

    // Text on either side of the NUL participates in the authenticated bytes:
    // the main golden tag covers `前\u{0000}后` whole, so dropping either side
    // while keeping the old tag is a mismatch rather than a truncation.
    let suffix_dropped = r#"{"format":1,"algorithm":"HMAC-SHA256","key_id":"密钥\n🙂","key_version":42,"fields":["前u0000","世界🙂\n第二行","","世界🙂\n第二行"],"tag":"7474105d623bb03a81eb00b34545fcaf7a8c24002c5a6e58ecfdc6172e1d7f9c"}"#
        .replace("u0000", "\\u0000");
    let prefix_dropped = r#"{"format":1,"algorithm":"HMAC-SHA256","key_id":"密钥\n🙂","key_version":42,"fields":["u0000后","世界🙂\n第二行","","世界🙂\n第二行"],"tag":"7474105d623bb03a81eb00b34545fcaf7a8c24002c5a6e58ecfdc6172e1d7f9c"}"#
        .replace("u0000", "\\u0000");
    expect_external_mismatch(suffix_dropped.as_bytes(), EXT_KEY);
    expect_external_mismatch(prefix_dropped.as_bytes(), EXT_KEY);
}

#[test]
fn changed_content_invalidates_old_external_tag() {
    // All variants stay structurally legal JSON and keep the ORIGINAL golden
    // tag; only the decoded content moves. Each must be exit 1, never exit 2
    // and never valid.

    // Delete the NUL from `前\u{0000}后`.
    let nul_deleted = r#"{"format":1,"algorithm":"HMAC-SHA256","key_id":"密钥\n🙂","key_version":42,"fields":["前后","世界🙂\n第二行","","世界🙂\n第二行"],"tag":"7474105d623bb03a81eb00b34545fcaf7a8c24002c5a6e58ecfdc6172e1d7f9c"}"#;
    expect_external_mismatch(nul_deleted.as_bytes(), EXT_KEY);

    // Replace every real newline with the two literal characters backslash
    // and 'n' (JSON "\\n"): a representation of different text, not an escape.
    let literal_backslash_n = r#"{"format":1,"algorithm":"HMAC-SHA256","key_id":"密钥\\n🙂","key_version":42,"fields":["前u0000后","世界🙂\\n第二行","","世界🙂\\n第二行"],"tag":"7474105d623bb03a81eb00b34545fcaf7a8c24002c5a6e58ecfdc6172e1d7f9c"}"#
        .replace("u0000", "\\u0000");
    expect_external_mismatch(literal_backslash_n.as_bytes(), EXT_KEY);

    // Merge away the duplicated field: repeats must not be deduplicated.
    let duplicate_collapsed = r#"{"format":1,"algorithm":"HMAC-SHA256","key_id":"密钥\n🙂","key_version":42,"fields":["前u0000后","世界🙂\n第二行",""],"tag":"7474105d623bb03a81eb00b34545fcaf7a8c24002c5a6e58ecfdc6172e1d7f9c"}"#
        .replace("u0000", "\\u0000");
    expect_external_mismatch(duplicate_collapsed.as_bytes(), EXT_KEY);

    // Drop the empty field (different field count).
    let empty_dropped = r#"{"format":1,"algorithm":"HMAC-SHA256","key_id":"密钥\n🙂","key_version":42,"fields":["前u0000后","世界🙂\n第二行","世界🙂\n第二行"],"tag":"7474105d623bb03a81eb00b34545fcaf7a8c24002c5a6e58ecfdc6172e1d7f9c"}"#
        .replace("u0000", "\\u0000");
    expect_external_mismatch(empty_dropped.as_bytes(), EXT_KEY);

    // Reorder two fields: order is authenticated.
    let reordered = r#"{"format":1,"algorithm":"HMAC-SHA256","key_id":"密钥\n🙂","key_version":42,"fields":["世界🙂\n第二行","前u0000后","","世界🙂\n第二行"],"tag":"7474105d623bb03a81eb00b34545fcaf7a8c24002c5a6e58ecfdc6172e1d7f9c"}"#
        .replace("u0000", "\\u0000");
    expect_external_mismatch(reordered.as_bytes(), EXT_KEY);
}

