fn run_verify_raw(args: &[&str], input: &[u8]) -> Output {
    let mut cmd = authnote();
    cmd.arg("verify");
    for a in args {
        cmd.arg(a);
    }
    use std::io::Write;
    use std::process::Stdio;
    let mut child = cmd
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("failed to spawn authnote");
    child
        .stdin
